      "ti": "እዚ ናይ ስኒ ሕክምና ብተወሳኺ መድሕነይ ዝተሸፈነ ድዩ፧",
      "om": "Yaalli ilkaanii kun inshuraansii dabalataatiin kaffalamaa?",
      "en": "Is this dental treatment covered by my supplementary insurance?"
