      "ti": "ናይ ገዛ ክራይ ደገፍን ናይ ጥዕና ደገፍን ብኸመይ ክሓትት ይኽእል፧",
      "om": "Gargaarsa kireeffannaafi fayyaa akkamitti gaafachuu danda'a?",
      "en": "How can I apply for rent allowance and healthcare allowance from the Tax Authority?"
