      "ti": "ናይ ዓመት ናይ ኤሌክትሪክ ሕሳብ ካብቲ ዝተጸበኽዎ በሊጹ።",
      "om": "Herreegni humnaa kan waggaa isa tilmaamame caaleera.",
      "en": "The annual energy statement was higher than expected."
